-- ============================================================================
-- D-040 Phase 3 MVP: content_tracks table for CMS-managed 3 tabs data
-- ============================================================================
-- @reference D-039 (Phase 1+2 JSON+progress) → D-040 (Phase 3 Supabase CMS)
-- @created 2026-05-19
-- @apply  Supabase SQL Editor at https://supabase.com/dashboard/project/<id>/sql
--
-- This migration:
--   1. Creates content_tracks table (1 row per track, payload = full JSON blob)
--   2. RLS: deny all anon; service_role + authenticated bypass
--   3. Seeds 3 initial rows from lib/{gamedev,fashion,stem}-data.json content
--      (snapshot at 2026-05-19 — anh can edit via /admin/content UI after)
--
-- Rollback:
--   DROP TABLE IF EXISTS public.content_tracks CASCADE;
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.content_tracks (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  track       text NOT NULL UNIQUE CHECK (track IN ('gamedev', 'fashion', 'stem')),
  payload     jsonb NOT NULL,
  version     int NOT NULL DEFAULT 1,
  updated_by  text DEFAULT 'system',
  updated_at  timestamptz NOT NULL DEFAULT now(),
  published   boolean NOT NULL DEFAULT true
);

CREATE INDEX IF NOT EXISTS idx_content_tracks_track_published
  ON public.content_tracks (track) WHERE published = true;

-- Bump version + timestamp on update
CREATE OR REPLACE FUNCTION public.bump_content_tracks_version()
RETURNS TRIGGER AS $$
BEGIN
  NEW.version = OLD.version + 1;
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_bump_content_tracks_version ON public.content_tracks;
CREATE TRIGGER trg_bump_content_tracks_version
  BEFORE UPDATE ON public.content_tracks
  FOR EACH ROW WHEN (OLD.payload IS DISTINCT FROM NEW.payload)
  EXECUTE FUNCTION public.bump_content_tracks_version();

-- RLS — deny anon, allow service_role (server only via API)
ALTER TABLE public.content_tracks ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "service_role_full_access" ON public.content_tracks;
CREATE POLICY "service_role_full_access" ON public.content_tracks
  FOR ALL TO service_role USING (true) WITH CHECK (true);

